{"baseRevision": 1, "code": "
const S = {stone:1, wood:2, glass:17, copper:12, gold:11, lamp:13, sand:6};
// 修正：重做前墙，使门与两扇窗都朝 -Z 可见
mf.erase([-6,2,-5],[13,7,1]);
mf.group('facade', () => {
  // 墙砖：底饰边
  mf.box([-6,2,-5],[13,1,1],{style:S.sand});
  // 左段 x-6..-6，门洞 x=-1..1 y=2..4，窗洞 x=-5..-4 与 x=4..5 在 y=3..5
  const solid = [];
  for (let x=-6; x<=6; x++){
    const inDoor = x>=-1 && x<=1;
    const inWinL = x>=-5 && x<=-4;
    const inWinR = x>=4 && x<=5;
    for (let y=3; y<=8; y++){
      if (inDoor && y<=4) continue;
      if (inWinL && y>=3 && y<=5) continue;
      if (inWinR && y>=3 && y<=5) continue;
      solid.push([x,y]);
    }
  }
  // 连续盒合并（按行）
  const rows = {};
  for (const [x,y] of solid){ (rows[y]=rows[y]||[]).push(x); }
  for (const y of Object.keys(rows)){
    const xs = rows[y].sort((a,b)=>a-b);
    let start = xs[0], prev = xs[0];
    for (let i=1;i<=xs.length;i++){
      const x = xs[i];
      if (x !== prev+1){
        mf.box([start,+y,-5],[prev-start+1,1,1],{style:S.copper});
        start = x;
      }
      prev = x;
    }
  }
});
// 窗：玻璃内嵌 + 金色窗框与窗棂
mf.erase([-5,3,-5],[2,3,1]); mf.erase([4,3,-5],[2,3,1]);
mf.group('windows2', () => {
  for (const x of [-5,4]){
    mf.box([x,3,-5],[2,3,1],{style:S.glass});
    mf.box([x,4,-6],[2,1,1],{style:S.gold});   // 横窗棂
    mf.box([x+1,3,-6],[1,3,1],{style:S.gold}); // 竖窗棂（外侧）
    mf.box([x-1,2,-6],[1,1,1],{style:S.gold}); // 外框下
    mf.box([x-1,6,-6],[4,1,1],{style:S.gold});
  }
});
// 门：外框加厚、门扇凹入、上方小气窗
mf.group('door2', () => {
  mf.box([-1,2,-5],[3,3,1],{style:S.wood});
  mf.box([0,3,-6],[1,1,1],{style:S.gold});    // 门钮
  mf.box([-2,2,-6],[1,4,1],{style:S.gold});
  mf.box([2,2,-6],[1,4,1],{style:S.gold});
  mf.box([-2,6,-6],[5,1,1],{style:S.gold});
  // 屋面挂牌/门灯
  mf.box([-1,7,-6],[3,1,1],{style:S.wood});
  mf.box([-3,7,-6],[1,1,1],{style:S.lamp});
  mf.box([3,7,-6],[1,1,1],{style:S.lamp});
});
// 台阶：三级，更清晰
mf.erase([-2,0,-7],[5,1,1]);
mf.group('steps2', () => {
  mf.box([-2,1,-6],[5,1,1],{style:S.sand});
  mf.box([-2,0,-6],[5,1,1],{style:S.sand});
  mf.box([-2,0,-7],[5,1,1],{style:S.stone});
  mf.box([-3,1,-6],[1,1,1],{style:S.copper});
  mf.box([3,1,-6],[1,1,1],{style:S.copper});
});
", "dryRun": false, "mode": "apply", "seed": 7}

